#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main(void) {
    printf("before fork: one process\n");
    fflush(stdout);                // avoid duplicated buffered output in child

    pid_t pid = fork();            // returns twice: 0 in child, child PID in parent
    if (pid == 0) {                // child branch
        printf("child  sees pid=%d\n", getpid());
        exit(0);
    }
    waitpid(pid, NULL, 0);         // parent: reap child so it cannot zombify
    printf("parent sees child pid=%d\n", pid);
    return 0;
}

#include <pthread.h>
#include <stdio.h>

static __thread int slot_id;       // thread-local: private per thread

static void *worker(void *arg) {
    slot_id = *(int *)arg;
    printf("worker sees slot %d\n", slot_id);
    return NULL;
}

int main(void) {
    pthread_t t[2];
    int ids[2] = {1, 2};
    for (int i = 0; i < 2; i++)
        pthread_create(&t[i], NULL, worker, &ids[i]);
    for (int i = 0; i < 2; i++)
        pthread_join(t[i], NULL);
    return 0;
}

